-- An `ON UPDATE CASCADE` child with six identical indexes: the repointed row is refused by
-- the one created first, as 18.6 enters it into each in creation order.
-- @setup
CREATE TABLE p (k text PRIMARY KEY);
INSERT INTO p VALUES ('a');
CREATE TABLE c (k text REFERENCES p ON UPDATE CASCADE, pad text);
CREATE INDEX c_1 ON c (pad, k);
CREATE INDEX c_2 ON c (pad, k);
CREATE INDEX c_3 ON c (pad, k);
CREATE INDEX c_4 ON c (pad, k);
CREATE INDEX c_5 ON c (pad, k);
CREATE INDEX c_6 ON c (pad, k);
INSERT INTO c VALUES ('a', '');
-- @test
-- @expect-error: the first-created index
-- @expect-message
-- @profile-lock
UPDATE p SET k = '36NrX4uqE8dJKMHdThcehgzNKB6jE5lAoqzMoS0biIH50qEQWARsMQ97WfbKPNC70AYw7VIXgIpsrVLzKMmAZXBb2TyYdzQVvhM9' WHERE k = 'a';
